<?php foreach (App\Models\Pendaftar::all() as $p) { if (!App\Models\PaymentTransaction::where("pendaftar_id", $p->id)->exists()) { App\Models\PaymentTransaction::create(["pendaftar_id" => $p->id, "order_id" => "REG-" . $p->no_pendaftaran, "amount" => $p->gelombang->biaya_daftar ?? 350000, "currency" => "IDR", "payment_method" => "bank_transfer", "payment_type" => "bank_transfer", "status" => strtolower($p->status) === "paid" ? "paid" : "pending", "gateway" => "manual", "created_at" => $p->created_at, "updated_at" => $p->updated_at, "paid_at" => strtolower($p->status) === "paid" ? now() : null]); } } echo "Done\n";
